diff --git a/mail/themes/shared/mail/accountHub.css b/mail/themes/shared/mail/accountHub.css
index 3caabdcb394..cb01fd8efeb 100644
--- a/mail/themes/shared/mail/accountHub.css
+++ b/mail/themes/shared/mail/accountHub.css
@@ -16,36 +16,35 @@ dialog {
   --hub-account-button-background-hover: light-dark(var(--color-ink-10), var(--color-gray-80));
   --hub-account-button-background-hover-active: light-dark(var(--color-gray-10), var(--color-gray-90));
   --hub-account-button-border-color: light-dark(var(--color-gray-30), var(--color-gray-60));
-  --hub-account-primary-button-color: light-dark(#feffff, #1a202c);
-  --hub-account-primary-button-background: light-dark(#1373d9, #58c9ff);
-  --hub-account-primary-button-background-hover: light-dark(#175fb6, #32aeff);
-  --hub-account-primary-button-background-active: light-dark(#19518f, #1b90f5);
-  --hub-account-primary-button-background-focus: light-dark(#175FB6, #32aeff);
-  --hub-account-primary-button-border: light-dark(#175fb6, #32aeff);
-  --hub-account-primary-button-border-active: light-dark(#19518f, #1b90f5);
+  --hub-account-primary-button-color: var(--color-neutral-base);
+  --hub-account-primary-button-background: var(--color-primary-default);
+  --hub-account-primary-button-background-hover: var(--color-primary-hover);
+  --hub-account-primary-button-background-active: var(--color-primary-pressed);
+  --hub-account-primary-button-background-focus: var(--color-primary-hover);
+  --hub-account-primary-button-border: var(--color-primary-hover);
+  --hub-account-primary-button-border-active: var(--color-primary-pressed);
   --hub-account-secondary-button-color: light-dark(#18181b, #eeeef0);
-  --hub-account-secondary-button-background: light-dark(#f7f7f7, #262d3b);
-  --hub-account-secondary-button-background-hover: light-dark(#f7f7f7, #1a202c);
-  --hub-account-secondary-button-background-active: light-dark(#e4e4e7, #18181b);
-  --hub-account-secondary-button-background-focus: light-dark(#f7f7f7, #1a202c);
-  --hub-account-secondary-button-border: light-dark(#e4e4e7, #303a4a);
-  --hub-account-secondary-button-border-active: light-dark(#777580, #3d4d67);
-  --hub-account-button-outline-focus: light-dark(#1373d9, #58c9ff);
-  --hub-account-button-hover-active-color: #e4e4e7;
-  --hub-account-footer-link-color: light-dark(#1373d9, #58c9ff);
-  --hub-notification-background-color-warning: var(--color-yellow-30);
-  --hub-border-color: light-dark(#f0f8ff, #58c9ff);
-  --hub-divider-color: light-dark(#ffffff, #1a202c);
+  --hub-account-secondary-button-background: var(--color-neutral-subtle);
+  --hub-account-secondary-button-background-hover: light-dark(var(--color-neutral-subtle), var(--color-neutral-base));
+  --hub-account-secondary-button-background-active: light-dark(var(--color-neutral-border), var(--color-neutral-lower));
+  --hub-account-secondary-button-background-focus: light-dark(var(--color-neutral-subtle), var(--color-neutral-base));
+  --hub-account-secondary-button-border: var(--color-neutral-border);
+  --hub-account-secondary-button-border-active: var(--color-neutral-border-intense);
+  --hub-account-button-outline-focus: var(--color-primary-hover);
+  --hub-account-button-hover-active-color:  light-dark(var(--color-neutral-border), var(--color-neutral-lower));
+  --hub-account-footer-link-color: var(--color-primary-default);
+  --hub-border-color: light-dark(var(--color-primary-soft), var(--color-primary-default));
+  --hub-divider-color: var(--color-neutral-base);

   --hub-box-shadow: 0 2px 4px rgba(58, 57, 68, 0.3);
   --hub-input-height: 33px;
   --hub-input-border-radius: 3px;
   --hub-input-border-color: color-mix(in srgb, currentColor 50%, transparent);
   --hub-close-button-color: light-dark(#18181b, #eeeef0);
-  --hub-close-button-hover-background: light-dark(#f7f7f7, #18181b);
-  --hub-close-button-active-background: light-dark(#bdbdbd, #262d3b);
-  --hub-close-button-focus-background: light-dark(#e4e4e7, #18181b);
-  --hub-close-button-focus-outline-color: light-dark(#4c4d58, #3d4d67);
+  --hub-close-button-hover-background: var(--color-neutral-subtle);
+  --hub-close-button-active-background:var(--color-text-muted);
+  --hub-close-button-focus-background: var(--color-neutral-subtle);
+  --hub-close-button-focus-outline-color: var(--color-neutral-border-intense);
   /* TODO: apply dark mode styling */
 }

diff --git a/mail/themes/shared/mail/accountHubForms.css b/mail/themes/shared/mail/accountHubForms.css
index 3c6d35455e4..fa701abbbdc 100644
--- a/mail/themes/shared/mail/accountHubForms.css
+++ b/mail/themes/shared/mail/accountHubForms.css
@@ -5,7 +5,7 @@
 @namespace xul "http://www.mozilla.org/keymaster/gatekeeper/there.is.only.xul";

 form {
-  --hub-input-bg-color: light-dark(#feffff, #18181b);
+  --hub-input-bg-color: light-dark(var(--color-neutral-base), #18181b);

   grid-row: header / footer;

@@ -27,14 +27,14 @@ form {
   label {
     font-size: 1.2rem;
     line-height: 1;
-    color: light-dark(#175fb6, #feffff);
+    color: light-dark(var(--color-primary-hover), #feffff);

     &.animated {
       position: absolute;
       background-color: var(--hub-input-bg-color);
       border-radius: 3px;
       transform-origin: left center;
-      color: light-dark(#4c4d58, #d9d9de);
+      color: var(--color-text-secondary);
       padding: 3px;
       margin-inline-start: 7px;
       font-weight: 200;
@@ -52,25 +52,25 @@ form {
     margin-inline: 0;
     padding-block: 12px;
     padding-inline: 9px 14px;
-    border: 1px solid light-dark(#e4e4e7, #303a4a);
+    border: 1px solid var(--color-neutral-border);
     background-color: var(--hub-input-bg-color);
     font-weight: 200;

     &:user-invalid {
-      border-color: light-dark(#991b1b, #fca5a5);
+      border-color: light-dark(var(--color-danger-default), var(--color-danger-pressed));

       &:focus {
-        border-color: light-dark(#991b1b, #fca5a5);
+        border-color: light-dark(var(--color-danger-default), var(--color-danger-pressed));
       }

       & ~ label {
-        color: light-dark(#991b1b, #fca5a5);
+        color: light-dark(var(--color-danger-default), var(--color-danger-pressed));
       }
     }

     &::placeholder {
       font-weight: 200;
-      color: light-dark(#4c4d58, #d9d9de);
+      color: var(--color-text-secondary);
     }

     &.animated {
@@ -80,7 +80,7 @@ form {
     }

     &:focus {
-      border-color: light-dark(#175fb6, #58c9ff);
+      border-color: light-dark(var(--color-primary-hover), var(--color-primary-default));
     }

     &:focus-visible {
@@ -92,7 +92,7 @@ form {
       transform: translateY(-102%);
       font-weight: normal;
       cursor: default;
-      background-color: light-dark(#feffff, #1a202c);
+      background-color: var(--color-neutral-base);
     }
   }

